// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: montserratFamily } = loadMontserrat();



export type HouseCrossSectionProps = Record<string, any>;

const HouseCrossSection: React.FC<HouseCrossSectionProps> = ({
  backgroundColor = "#f3f4f6",
  transparentBackground = false,
  durationInSeconds = 8,
  houseColor = "#1e293b",
  roofColor = "#0f172a",
  roomColor = "#ffffff",
  textColor = "#334155",
  roomTexts = ["Career programs", "Experience", "clubs", "mentorship"],
  textAppearFrames = [40, 50, 60, 70],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Fallback to exactly 4 items for the ring
  const displayTexts = [...roomTexts, "", "", "", ""].slice(0, 4);
  const displayTimes = [...textAppearFrames, 40, 50, 60, 70].slice(0, 4);

  // Constants for layout scaling
  const scaleRatio = Math.min(width / 1920, height / 1080);
  const cx = 1920 / 2;
  const cy = 1080 / 2;
  const R = 400; // Ring radius
  const textRadius = 460;
  
  // Starting angles for the 4 texts (Top Right, Bottom Right, Bottom Left, Top Left)
  const textAngles = [-45, 45, 135, 225];

  // Animations
  const baseP = spring({ fps, frame: frame - 5, config: { damping: 12 } });
  const roofP = spring({ fps, frame: frame - 15, config: { damping: 12 } });
  const detailsP = spring({ fps, frame: frame - 25, config: { damping: 12 } });
  const yardP = spring({ fps, frame: frame - 10, config: { damping: 15 } });

  const ringProgress = spring({
    fps,
    frame: frame - 20,
    config: { damping: 200, mass: 2, stiffness: 50 },
  });

  const ringCircumference = 2 * Math.PI * R;
  const ringStrokeOffset = interpolate(ringProgress, [0, 1], [ringCircumference, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Slow global rotation to make the ring and text feel alive
  const globalRotation = interpolate(frame, [0, fps * durationInSeconds], [0, 45]);
  
  const houseOpacity = interpolate(baseP, [0, 0.5], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: montserratFamily }}>
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <div
          style={{
            position: "relative",
            width: 1920,
            height: 1080,
            transform: `scale(${scaleRatio})`,
            transition: "none",
          }}
        >
          {/* Subdued Background Yard */}
          <svg width={1920} height={1080} style={{ position: "absolute", top: 0, left: 0, overflow: 'visible', transition: 'none' }}>
            <circle cx={cx} cy={cy} r={R - 20} fill={roofColor} opacity={0.03 * yardP} />
          </svg>

          {/* Ring and Dots */}
          <svg width={1920} height={1080} style={{ position: "absolute", top: 0, left: 0, overflow: 'visible', transition: 'none' }}>
            <circle 
              cx={cx} cy={cy} r={R} 
              fill="none" 
              stroke={roofColor} 
              strokeWidth="4" 
              strokeDasharray={ringCircumference} 
              strokeDashoffset={ringStrokeOffset} 
              opacity={0.15} 
              strokeLinecap="round"
            />

            {textAngles.map((angle, index) => {
              const currentAngle = angle + globalRotation;
              const rad = (currentAngle * Math.PI) / 180;
              const dotX = cx + Math.cos(rad) * R;
              const dotY = cy + Math.sin(rad) * R;
              const tProgress = spring({
                fps, frame: frame - displayTimes[index], config: { damping: 12 }
              });
              
              return (
                <circle 
                  key={`dot-${index}`}
                  cx={dotX} cy={dotY} 
                  r={Math.max(0, 10 * tProgress)} 
                  fill={roofColor} 
                />
              );
            })}
          </svg>

          {/* Texts */}
          {textAngles.map((angle, index) => {
            const currentAngle = angle + globalRotation;
            const rad = (currentAngle * Math.PI) / 180;
            const textX = cx + Math.cos(rad) * textRadius;
            const textY = cy + Math.sin(rad) * textRadius;
            const tProgress = spring({
              fps, frame: frame - displayTimes[index], config: { damping: 12 }
            });

            return (
              <div
                key={`text-${index}`}
                style={{
                  position: "absolute",
                  left: textX,
                  top: textY,
                  transform: `translate(-50%, -50%) scale(${Math.max(0, tProgress)})`,
                  opacity: tProgress,
                  color: textColor,
                  fontSize: 42,
                  fontWeight: 800,
                  textAlign: "center",
                  textTransform: "capitalize",
                  backgroundColor: roomColor,
                  padding: "16px 32px",
                  borderRadius: "24px",
                  boxShadow: "0 10px 25px rgba(0,0,0,0.1)",
                  border: `2px solid ${roofColor}20`,
                  maxWidth: "350px",
                  wordWrap: "break-word",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  zIndex: 20,
                  transition: "none",
                }}
              >
                {displayTexts[index]}
              </div>
            );
          })}

          {/* Center 2D Detailed House */}
          <div
            style={{
              position: 'absolute',
              left: cx,
              top: cy,
              transform: 'translate(-50%, -50%)',
              width: 400,
              height: 400,
              zIndex: 10,
              opacity: houseOpacity,
              transition: "none",
            }}
          >
            <svg width="400" height="400" viewBox="0 0 400 400" style={{ overflow: 'visible', transition: 'none' }}>
              
              {/* Back Elements (Bushes) */}
              <g style={{ transformOrigin: '200px 360px', transform: `scale(${Math.max(0, baseP)})`, transition: 'none' }}>
                <circle cx="60" cy="350" r="35" fill={roofColor} opacity="0.6" />
                <circle cx="340" cy="350" r="35" fill={roofColor} opacity="0.6" />
              </g>

              {/* Main Structure */}
              <g style={{ transformOrigin: '200px 350px', transform: `scale(${Math.max(0, baseP)})`, transition: 'none' }}>
                <rect x="80" y="180" width="240" height="170" fill={houseColor} rx="8" />
                <rect x="270" y="90" width="40" height="80" fill={houseColor} />
                <rect x="260" y="80" width="60" height="20" fill={roofColor} />
              </g>
              
              {/* Roof */}
              <g style={{ transformOrigin: '200px 180px', transform: `scale(${Math.max(0, roofP)})`, transition: 'none' }}>
                <path d="M 40 180 L 200 60 L 360 180 Z" fill={roofColor} strokeLinejoin="round" />
                <path d="M 40 180 L 200 60 L 360 180" fill="none" stroke={houseColor} strokeWidth="10" strokeLinecap="round" strokeLinejoin="round" />
              </g>
              
              {/* Details (Door, Windows) */}
              <g style={{ transformOrigin: '200px 295px', transform: `scale(${Math.max(0, detailsP)})`, transition: 'none' }}>
                <rect x="160" y="240" width="80" height="110" fill={roomColor} rx="8" />
                <rect x="170" y="250" width="60" height="40" fill={houseColor} opacity="0.1" rx="4" />
                <circle cx="225" cy="300" r="6" fill={houseColor} />
                
                <rect x="100" y="220" width="40" height="50" fill={roomColor} rx="6" />
                <rect x="260" y="220" width="40" height="50" fill={roomColor} rx="6" />
                
                <line x1="120" y1="220" x2="120" y2="270" stroke={houseColor} strokeWidth="4" />
                <line x1="100" y1="245" x2="140" y2="245" stroke={houseColor} strokeWidth="4" />
                <line x1="280" y1="220" x2="280" y2="270" stroke={houseColor} strokeWidth="4" />
                <line x1="260" y1="245" x2="300" y2="245" stroke={houseColor} strokeWidth="4" />
              </g>
              
              {/* Front Elements (Bushes and Steps) */}
              <g style={{ transformOrigin: '200px 360px', transform: `scale(${Math.max(0, baseP)})`, transition: 'none' }}>
                <circle cx="100" cy="360" r="25" fill={roofColor} opacity="0.8" />
                <circle cx="300" cy="360" r="25" fill={roofColor} opacity="0.8" />
                
                <rect x="140" y="350" width="120" height="10" fill={roofColor} rx="4" />
                <rect x="120" y="360" width="160" height="10" fill={roofColor} rx="4" />
              </g>
            </svg>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default HouseCrossSection;